<?php
 namespace QQWorld\Sales\Model\Order; class InvoiceTest extends \PHPUnit\Framework\TestCase { private $_collection; protected function setUp() { $this->_collection = \QQWorld\TestFramework\Helper\Bootstrap::getObjectManager()->create( \QQWorld\Sales\Model\ResourceModel\Order\Collection::class ); } public function testOrderTotalItemCount() { $expectedResult = [['total_item_count' => 1]]; $actualResult = []; foreach ($this->_collection->getItems() as $order) { $actualResult[] = ['total_item_count' => $order->getData('total_item_count')]; } $this->assertEquals($expectedResult, $actualResult); } } 